  window.BURSTLAB_GLOSSARY = [
    {term:'Vazão',definition:'Quantidade de operações concluídas por unidade de tempo. Diferencie vazão de aceitação HTTP e de conclusão de trabalho.'},
    {term:'Latência',definition:'Tempo decorrido entre dois eventos definidos, como enviar uma chamada a B e receber seu resultado. Inclui espera apenas se esse for o perímetro medido.'},
    {term:'Concorrência',definition:'Número de operações em andamento simultaneamente. Não é uma taxa: oito chamadas ativas e oito chamadas por segundo medem coisas diferentes.'},
    {term:'Backlog',definition:'Quantidade de trabalho pendente. A idade do mais antigo complementa a contagem e mostra risco de violar prazos.'},
    {term:'Redis',definition:'Servidor de estruturas de dados em memória. Neste projeto armazena o saldo do bucket e leases de admissão; não encaminha o payload HTTP de A para B.'},
    {term:'Lua',definition:'Linguagem de script executada no Redis. Agrupa leitura, reposição, verificação e débito numa decisão atômica curta.'},
    {term:'Amazon SQS',definition:'Serviço de filas gerenciado da AWS. Guarda mensagens de trabalho; consumidores recebem, processam e removem explicitamente as mensagens.'},
    {term:'Lease',definition:'Permissão com prazo de validade. Expirar uma lease recupera uma vaga lógica após queda, mas não interrompe automaticamente uma chamada remota ainda ativa.'},
    {term:'Outbox',definition:'Tabela de intenções de publicação gravada na mesma transação do estado de negócio. Um publicador envia pendências e pode reenviá-las após falha; consumidores precisam suportar duplicatas.'},
    {term:'Visibility timeout',definition:'Tempo em que uma mensagem recebida fica normalmente oculta dos demais consumidores. A mensagem continua na fila até DeleteMessage; visibilidade não substitui idempotência.'},
    {term:'DLQ',definition:'Dead-letter queue: fila de trabalhos que precisam de diagnóstico e reprocessamento controlado. No BurstLab, falhas terminais são encaminhadas por outbox.'},
    {term:'Token bucket',definition:'Algoritmo que acumula até C permissões e as repõe à taxa r. Permite bursts finitos e limita o ritmo sustentado; não garante espaçamento uniforme.'},
    {term:'Idempotência',definition:'Propriedade de repetir a mesma operação lógica sem repetir seu efeito. Requer chave estável, comparação do payload e persistência coerente com o efeito.'},
    {term:'Atomicidade',definition:'Uma operação composta é observada como uma única decisão dentro do sistema que a executa. Lua atômico no Redis não cria uma transação com SQS e B.'},
    {term:'Fail-closed',definition:'Política de negar execução quando não é possível confirmar admissão. Preserva proteção sacrificando disponibilidade imediata.'},
    {term:'Fail-open',definition:'Política de permitir mesmo sem confirmar o limitador. Pode preservar disponibilidade de curto prazo, mas abandona o teto global naquele intervalo.'},
    {term:'Jitter',definition:'Variação adicionada à espera entre retries para evitar que muitos clientes repitam juntos. No sistema real usa aleatoriedade; no simulador a política é modelada.'},
    {term:'Backoff',definition:'Espera crescente entre novas tentativas. Precisa de limite máximo, prazo total e idempotência, além da espera em si.'},
    {term:'Prefetch',definition:'Receber mensagens antecipadamente antes de existir capacidade para executá-las. Sem limite, aumenta invisibilidade e memória sem aumentar throughput.'},
    {term:'Hash slot',definition:'Partição lógica de chaves em Redis Cluster. Chaves acessadas pelo mesmo script precisam estar no mesmo slot; uma hash tag entre chaves ajuda a alinhá-las.'},
    {term:'Deadline',definition:'Instante final após o qual a operação não deve continuar iniciando trabalho. O orçamento restante diminui ao longo de todas as etapas.'},
    {term:'At-least-once',definition:'Entrega pelo menos uma vez, com possibilidade de repetição. O consumidor precisa tolerar e reconciliar mensagens duplicadas.'},
    {term:'Tenant',definition:'Cliente ou organização cujo tráfego pode exigir cota, autorização e isolamento próprios. Um limite global não assegura equidade entre tenants.'},
    {term:'p99',definition:'Percentil que contém aproximadamente 99% das observações. Exige amostra e janela adequadas; não é um limite máximo nem substitui analisar falhas.'},
    {term:'SLO',definition:'Objetivo mensurável de serviço, como proporção de jobs concluídos em até certo prazo. Deve distinguir aceite, execução, falha e rejeição.'},
    {term:'OpenTelemetry',definition:'Padrões e ferramentas para instrumentar e transportar traces, métricas e logs, com correlação entre componentes.'},
    {term:'Semáforo',definition:'Controle de quantidade de permissões simultâneas. Uma permissão é liberada ao terminar; ao contrário de um token de taxa, que não é devolvido.'}
  ];
